-- The games Xpeed Sim reads, with their cover art, kept in Xpeed's own database: Xpeed Sim and the app take the
-- covers from here (GET /api/sim/games and /api/sim/games/<key>/cover), never from a store or another site. The
-- covers were taken once from each game's public Steam store page (300x450 JPEG) and stored here as base64.
-- key is the game id Xpeed Sim writes in its laps (the reader ids: lmu, ac, acc, ...). Anyone may read the list;
-- only the server (service role) writes it.

CREATE TABLE public.sim_games (
  key text PRIMARY KEY CHECK (key ~ '^[a-z0-9]{1,32}$'),
  title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 80),
  sort_order integer NOT NULL,
  -- Where the cover came from (the game's Steam store app id), for the record.
  steam_app_id integer,
  cover_base64 text NOT NULL,
  cover_type text NOT NULL CHECK (cover_type IN ('image/jpeg', 'image/png', 'image/webp')),
  cover_sha256 text NOT NULL CHECK (cover_sha256 ~ '^[0-9a-f]{64}$'),
  cover_bytes integer NOT NULL CHECK (cover_bytes BETWEEN 1 AND 1048576),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.sim_games ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_sim_games ON public.sim_games FOR SELECT USING (true);
REVOKE ALL ON public.sim_games FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.sim_games TO anon, authenticated;
GRANT ALL ON public.sim_games TO service_role;

